@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  --background: oklch(0.9924 0 0);
  --foreground: oklch(0.1405 0.0044 285.82);

  --card: oklch(1 0 0);
  --card-foreground: oklch(0.1405 0.0044 285.82);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.1405 0.0044 285.82);

  --primary: oklch(0.5297 0.1615 258.75);
  --primary-foreground: oklch(1 0 0);

  --secondary: oklch(1 0 0);
  --secondary-foreground: oklch(0.2103 0.0059 285.88);

  --muted: oklch(0.9676 0.0013 286.37);
  --muted-foreground: oklch(0.5519 0.0137 285.94);

  --accent: oklch(0.9761 0.0012 286.38);
  --accent-foreground: oklch(0.2103 0.0059 285.88);

  --destructive: oklch(0.6368 0.2078 25.33);
  --destructive-foreground: oklch(0.9848 0 0);

  --border: oklch(0.9197 0.004 286.32);
  --input: oklch(0.9374 0.0016 286.37);
  --ring: oklch(0.5297 0.1615 258.75);

  --radius: 0.6rem;

  /* Shadow overrides — light theme, professional subtle shadows */
  --shadow-2xs: 0 1px 2px 0 rgba(0,0,0,0.04);
  --shadow-xs:  0 1px 2px 0 rgba(0,0,0,0.06);
  --shadow-sm:  0 1px 3px 0 rgba(0,0,0,0.08), 0 1px 2px -1px rgba(0,0,0,0.06);
  --shadow:     0 1px 3px 0 rgba(0,0,0,0.1),  0 1px 2px -1px rgba(0,0,0,0.08);
  --shadow-md:  0 4px 6px -1px rgba(0,59,153,0.1), 0 2px 4px -2px rgba(0,59,153,0.06);
  --shadow-lg:  0 8px 16px -2px rgba(0,59,153,0.12), 0 4px 6px -4px rgba(0,59,153,0.06), 0 0 0 1px rgba(0,59,153,0.04);
  --shadow-xl:  0 16px 24px -4px rgba(0,59,153,0.14), 0 8px 10px -6px rgba(0,59,153,0.08);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: var(--font-geist-sans), ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
